/* Mẫu: biến màu / spacing dùng chung — sửa tại đây khi đổi theme */
:root {
  --color-text: #142033;
  --color-muted: #64748b;
  --color-border: #d9e2ef;
  --color-surface: #ffffff;
  --radius-card: 1rem;
  --radius-btn: 0.5rem;
  --space-section: 2rem;
}

/* Mẫu: style nền toàn site (bổ sung Tailwind) */
:root {
  color-scheme: light;
}

body {
  @apply bg-slate-50 text-slate-800 font-sans antialiased;
  color: var(--color-text);
}

a {
  @apply text-inherit no-underline;
}

/* Mẫu: layout header, footer, container */
.container-wide {
  @apply mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8;
}

.section-block {
  margin-bottom: var(--space-section);
}

/* Ví dụ class riêng cho vùng header custom (thêm class vào AppHeader nếu cần) */
.site-header-bar {
  border-bottom: 1px solid var(--color-border);
}

/* Mẫu: component dùng chung — card, nút, nội dung bài viết */
.card-surface {
  @apply rounded-2xl bg-white shadow-soft ring-1 ring-slate-200;
}

.section-title {
  @apply mb-6 text-2xl font-bold leading-tight text-slate-900;
}

.rich-content h2,
.rich-content h3 {
  @apply mb-3 mt-6 font-bold text-slate-900;
}

.rich-content h2 {
  @apply text-2xl;
}

.rich-content h3 {
  @apply text-xl;
}

.rich-content p {
  @apply mb-4 leading-7 text-slate-700;
}

.rich-content ul {
  @apply mb-4 list-disc space-y-2 pl-6 text-slate-700;
}

.rich-content a {
  @apply text-brand-700 underline hover:text-brand-800;
}

/* Nút mẫu — dùng: <button class="btn-primary">...</button> */
.btn-primary {
  @apply inline-flex items-center justify-center rounded-lg bg-brand-600 px-4 py-2 text-sm font-semibold text-white transition hover:bg-brand-700;
}

.btn-outline {
  @apply inline-flex items-center justify-center rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-medium text-slate-700 transition hover:border-brand-400 hover:text-brand-700;
}

/**
 * Mẫu CSS thư viện tải về — đặt trong public/vendor/
 * URL: /vendor/sample-lib/sample-lib.css
 * Khai báo: nuxt.config.js → css: ['/vendor/sample-lib/sample-lib.css']
 */

.sample-lib-badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  background: #e0f2fe;
  color: #0369a1;
}

.sample-lib-ready {
  position: relative;
}

.sample-lib-ready::after {
  content: "";
  position: absolute;
  inset: -2px;
  border: 2px dashed #38bdf8;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0.6;
}

/**
 * Mẫu JS thư viện tải về (UMD) — đặt trong public/vendor/
 * URL: /vendor/sample-lib/sample-lib.js
 * Khai báo: nuxt.config.js → app.head.script
 *
 * Sau khi load: window.SampleLib.init('[data-sample-lib]')
 */
(function (global) {
  'use strict';

  var SampleLib = {
    version: '1.0.0-sample',

    init: function (selector) {
      if (!global.document) {
        return 0;
      }

      var query = selector || '[data-sample-lib]';
      var nodes = global.document.querySelectorAll(query);
      var i;

      for (i = 0; i < nodes.length; i += 1) {
        nodes[i].classList.add('sample-lib-ready');
      }

      return nodes.length;
    },
  };

  global.SampleLib = SampleLib;
})(typeof window !== 'undefined' ? window : this);

/**
 * Mẫu plugin client — gọi thư viện JS trong public/vendor/ sau khi script đã load.
 * Cần bật script trong nuxt.config.js → app.head.script
 */
export default defineNuxtPlugin(() => {
  const run = () => {
    if (typeof window.SampleLib?.init !== 'function') {
      return;
    }

    window.SampleLib.init('[data-sample-lib]');
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', run);
    return;
  }

  run();
});

